&= \mathop{\mathrm{E}}[ Y^2] - \mathop{\mathrm{E}}\sb*{2 Y \mathop{\mathrm{E}}(Y)} + \mathop{\mathrm{E}}\sb*{\left\{ * \right\}{\mathop{\mathrm{E}}(Y)}^2} && \text{Distributing expectations (linearity)} \\
&= \mathop{\mathrm{E}}[ Y^2] - 2\mathop{\mathrm{E}}(Y)\mathop{\mathrm{E}}\sb*{Y} + \left\{ * \right\}{\mathop{\mathrm{E}}(Y)}^2\mathop{\mathrm{E}}[1] && \text{Pulling constants out of expectations (linearity)} \\
&= \mathop{\mathrm{E}}[ Y^2] - 2\left\{ * \right\}{\mathop{\mathrm{E}}(Y)}^2 + \left\{ * \right\}{\mathop{\mathrm{E}}(Y)}^2] && \text{Recognizing a product of something with itself as a square} \\
&= \mathop{\mathrm{E}}[ Y^2] - \cancel{2}\left\{ * \right\}{\mathop{\mathrm{E}}(Y)}^2 + \cancel{\left\{ * \right\}{\mathop{\mathrm{E}}(Y)}^2}] && \text{Subtracting}
\end{aligned}
}

