\mathop{\mathrm{\mathop{\mathrm{V}}}}[Y] = \textcolor{blue}{\mathop{\mathrm{E}}\sb*{\mathop{\mathrm{\mathop{\mathrm{V}}}}(Y \mid W)}} + \textcolor{green}{\mathop{\mathrm{\mathop{\mathrm{V}}}}\sb*{\mathop{\mathrm{E}}(Y \mid W)}}


